import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

// Custom hook for interval functionality
function useInterval(callback, delay) {
  const savedCallback = useRef();

  // Remember the latest callback
  useEffect(() => {
    savedCallback.current = callback;
  }, [callback]);

  // Set up the interval
  useEffect(() => {
    function tick() {
      savedCallback.current();
    }
    if (delay !== null) {
      const id = setInterval(tick, delay);
      return () => clearInterval(id);
    }
  }, [delay]);
}

function App() {
  const [symbol, setSymbol] = useState('BBCA.JK');
  const [stockData, setStockData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [currencySymbol, setCurrencySymbol] = useState('Rp');
  const [realtime, setRealtime] = useState(false);
  const [refreshInterval, setRefreshInterval] = useState(30000); // 30 seconds by default
  const [lastFetched, setLastFetched] = useState(null);
  const [dataInfo, setDataInfo] = useState({
    isRealtime: false,
    delay: "15-20 minutes",
    source: "Yahoo Finance"
  });

  const fetchStock = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await axios.get("http://localhost:5000/stock", {
        params: { symbol }
      });

      if (res.data && res.data.data && Array.isArray(res.data.data)) {
        // Determine currency symbol based on stock symbol
        // Check for both .JK suffix and special Indonesian indices like ^JKSE
        const isIndonesianStock = symbol.endsWith('.JK') || 
                                 symbol === '^JKSE' || 
                                 symbol === '^IDXENERGY' ||
                                 symbol === '^IDXBASIC' ||
                                 symbol === '^IDXINDUST' ||
                                 symbol === '^IDXNONCYC' ||
                                 symbol === '^IDXCYCLIC' ||
                                 symbol === '^IDXHEALTH' ||
                                 symbol === '^IDXFINANCE' ||
                                 symbol === '^IDXTECHNO' ||
                                 symbol.startsWith('^IDX');

        setCurrencySymbol(isIndonesianStock ? 'Rp' : '$');

        // Sort the data array by date in descending order (newest first)
        const sortedData = [...res.data.data].sort((a, b) => {
          const dateA = new Date(a.Date || a.Datetime);
          const dateB = new Date(b.Date || b.Datetime);
          return dateB - dateA; // Descending order
        });

        // Update data info based on the exchange
        setDataInfo({
          isRealtime: false,
          delay: isIndonesianStock ? "15 minutes" : "15-20 minutes",
          source: "Yahoo Finance (yfinance)"
        });

        // Use sorted data
        setStockData(sortedData);
        setLastFetched(new Date());
      } else {
        setError('Invalid data format received from server');
        setStockData([]);
      }
    } catch (err) {
      console.error('Error details:', err);
      setStockData([]);

      if (err.response) {
        if (err.response.status === 404) {
          setError(`No data found for symbol: ${symbol}`);
        } else {
          setError(`Server error: ${err.response.data?.error || 'Unknown error'}`);
        }
      } else if (err.request) {
        setError('Server not responding. Please check if backend is running.');
      } else {
        setError(`Failed to fetch data: ${err.message}`);
      }
    } finally {
      setLoading(false);
    }
  };

  // Initial fetch
  useEffect(() => {
    fetchStock();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [symbol]);

  // Set up real-time updates using the custom interval hook
  useInterval(() => {
    if (realtime) {
      fetchStock();
    }
  }, refreshInterval);

  // Format date and time properly
  const formatDateTime = (dateString) => {
    if (!dateString) return '-';

    const date = new Date(dateString);
    if (isNaN(date.getTime())) return dateString; // Return original if invalid date

    // Format: DD-MM-YYYY HH:MM:SS
    return date.toLocaleString('id-ID', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false
    });
  };

  // Format relative time (e.g., "2 minutes ago")
  const getRelativeTime = (date) => {
    if (!date) return '';

    const seconds = Math.floor((new Date() - date) / 1000);

    let interval = Math.floor(seconds / 31536000);
    if (interval > 1) return `${interval} years ago`;
    if (interval === 1) return '1 year ago';

    interval = Math.floor(seconds / 2592000);
    if (interval > 1) return `${interval} months ago`;
    if (interval === 1) return '1 month ago';

    interval = Math.floor(seconds / 86400);
    if (interval > 1) return `${interval} days ago`;
    if (interval === 1) return '1 day ago';

    interval = Math.floor(seconds / 3600);
    if (interval > 1) return `${interval} hours ago`;
    if (interval === 1) return '1 hour ago';

    interval = Math.floor(seconds / 60);
    if (interval > 1) return `${interval} minutes ago`;
    if (interval === 1) return '1 minute ago';

    return seconds < 5 ? 'just now' : `${seconds} seconds ago`;
  };

  return (
    <div style={{ padding: '2rem' }}>
      <h1>Stock Data Viewer</h1>
      <div style={{ margin: '1rem 0', display: 'flex', gap: '10px', alignItems: 'center', flexWrap: 'wrap' }}>
        <input
          type="text"
          value={symbol}
          onChange={(e) => setSymbol(e.target.value)}
          placeholder="Enter stock symbol (e.g., BBCA.JK)"
          style={{ padding: '8px' }}
        />
        <button
          onClick={fetchStock}
          style={{ padding: '8px 16px', cursor: 'pointer' }}
          disabled={loading}
        >
          {loading ? 'Loading...' : 'Fetch Data'}
        </button>

        <div style={{ display: 'flex', alignItems: 'center', marginLeft: '20px' }}>
          <label style={{ marginRight: '10px' }}>
            <input
              type="checkbox"
              checked={realtime}
              onChange={(e) => setRealtime(e.target.checked)}
            />
            Real-time updates
          </label>

          {realtime && (
            <select 
              value={refreshInterval} 
              onChange={(e) => setRefreshInterval(Number(e.target.value))}
              style={{ padding: '5px' }}
            >
              <option value={5000}>5 seconds</option>
              <option value={10000}>10 seconds</option>
              <option value={30000}>30 seconds</option>
              <option value={60000}>1 minute</option>
              <option value={300000}>5 minutes</option>
            </select>
          )}
        </div>
      </div>

      {lastFetched && (
        <div style={{ fontSize: '12px', color: '#666', marginBottom: '10px' }}>
          Last updated: {formatDateTime(lastFetched)} ({getRelativeTime(lastFetched)})
          {realtime && <span> • Auto-refresh {refreshInterval/1000}s</span>}
          <div style={{ marginTop: '5px' }}>
            <span style={{ color: dataInfo.isRealtime ? 'green' : 'orange' }}>
              ⚠️ {dataInfo.isRealtime ? 'Real-time data' : `Delayed data (${dataInfo.delay} delay)`}
            </span> • Source: {dataInfo.source}
          </div>
        </div>
      )}

      {error && <div style={{ color: 'red', margin: '1rem 0' }}>{error}</div>}

      {loading ? (
        <p>Loading data...</p>
      ) : stockData.length > 0 ? (
        <div>
          <div style={{ 
            padding: '1rem', 
            marginBottom: '1rem', 
            backgroundColor: '#f8f9fa', 
            borderRadius: '5px',
            border: '1px solid #ddd'
          }}>
            <p>Showing data for: <strong>{symbol}</strong></p>
            {stockData.length > 0 && (
              <div>
                <h2>Last Price</h2>
                <div style={{ fontSize: '24px', fontWeight: 'bold', color: '#1a5276' }}>
                  {currencySymbol} {typeof stockData[0].Close === 'number' 
                    ? stockData[0].Close.toLocaleString() 
                    : '-'}
                </div>
                <div style={{ fontSize: '14px', color: '#666' }}>
                  as of {formatDateTime(stockData[0].Date || stockData[0].Datetime)}
                  <span style={{ marginLeft: '10px', color: 'orange', fontSize: '12px' }}>
                    (Delayed by approx. {dataInfo.delay})
                  </span>
                </div>
              </div>
            )}
          </div>

          <table border="1" cellPadding="5" style={{ marginTop: '1rem', borderCollapse: 'collapse' }}>
            <thead style={{ backgroundColor: '#f2f2f2' }}>
              <tr>
                <th>Date & Time</th>
                <th>Open</th>
                <th>High</th>
                <th>Low</th>
                <th>Close</th>
                <th>Volume</th>
              </tr>
            </thead>
            <tbody>
              {stockData.map((row, i) => (
                <tr key={i}>
                  <td>{formatDateTime(row.Date || row.Datetime)}</td>
                  <td>{currencySymbol} {typeof row.Open === 'number' ? row.Open.toLocaleString() : '-'}</td>
                  <td>{currencySymbol} {typeof row.High === 'number' ? row.High.toLocaleString() : '-'}</td>
                  <td>{currencySymbol} {typeof row.Low === 'number' ? row.Low.toLocaleString() : '-'}</td>
                  <td>{currencySymbol} {typeof row.Close === 'number' ? row.Close.toLocaleString() : '-'}</td>
                  <td>{typeof row.Volume === 'number' ? row.Volume.toLocaleString() : '-'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : !error && (
        <p>No data available. Please enter a valid stock symbol and fetch data.</p>
      )}

      <div style={{ marginTop: '20px', padding: '10px', backgroundColor: '#f9f9f9', border: '1px solid #ddd', borderRadius: '4px' }}>
        <h3>About Data Availability</h3>
        <p>
          <strong>Important:</strong> Yahoo Finance (yfinance) does not provide true real-time data for most markets:
        </p>
        <ul>
          <li>Data for most exchanges is delayed by 15-20 minutes</li>
          <li>Indonesian stocks (.JK) typically have a 15-minute delay</li>
          <li>The "Real-time updates" feature will refresh the data at your chosen interval but cannot bypass the exchange's delay</li>
        </ul>
        <p>
          For true real-time data, you would need to subscribe to a premium financial data provider API.
        </p>
      </div>
    </div>
  );
}

export default App;
